.embedded-video-v26 {
    position: relative;
    padding: $measure--small1;
    display: flex;
    flex-direction: column;

    .embedded-video-v26__triangles {
        position: absolute;
        top: 0;
        right: 0;
        width: $measure--huge3;
        height: $measure--huge3;
    }

    .cover-image__container {
        position: relative;

        &:hover {
            .cover-image__button {
                background: $color-purewhite;
                outline-color: $color-purewhite;

                &:before {
                    color: $color-nearblack;
                }
            }
        }

        &:before {
            position: absolute;
            width: 100%;
            height: 100%;
            background: linear-gradient(
                180deg,
                rgba(0, 0, 0, 0) 60%,
                rgba(0, 0, 0, 0.5) 100%
            );
            content: '';
            z-index: z-index('above');
            border-radius: $measure--half;
        }
    }

    .cover-image {
        border-radius: $measure--half;
    }

    .cover-image__content {
        position: absolute;
        bottom: $measure--small4;
        left: $measure--small4;
        display: flex;
        flex-direction: row;
        color: $color-purewhite;
        z-index: z-index('above');
    }

    .cover-image__intro {
        margin-top: 0;
        align-self: center;
        @include epsilontype;
    }

    .cover-image__button {
        background-color: $color-red50;
        width: $measure--medium6;
        height: $measure--medium6;
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        outline-offset: $measure--half * 0.8;
        outline-style: $border-style-solid;
        outline-width: $border-width-default;
        outline-color: $color-red50;
        margin-right: $measure--small2;

        &:before {
            content: '\f144';
            font-family: 'Font Awesome 6 Pro';
            color: $color-purewhite;
            @include zetatype;
        }
    }

    .youtube-video__wrapper {
        height: 0;
        padding-bottom: 56.25%;
        position: relative;
        width: 100%;

        iframe {
            height: 100%;
            left: 0;
            margin: 0;
            position: absolute;
            top: 0;
            width: 100%;
            border: none;
            border-radius: $measure--half;
        }
    }

    .youtube-video__caption-element--text,
    .youtube-video__caption-element--time {
        display: block;
    }

    .youtube-video__caption-element--time span {
        font-weight: $font-weight-extrablack;
    }
}

.embedded-video-v26[data-video-loaded='false'] {
    .youtube-video__wrapper {
        height: initial;
        padding-bottom: initial;
    }
}

// transscript accordion styles
.js .embedded-video-v26 .accordion-v26 {
    .accordion__heading {
        border-radius: $measure--half;
        border: $border-width-hairline $border-style-solid $color-nearblack;

        &[data-open='true'] {
            border-radius: $measure--half $measure--half 0 0;
            border: none;

            button {
                border-radius: $measure--half $measure--half 0 0;
                border-bottom: none;

                &:focus {
                    border-bottom: none;
                }
            }

            + .accordion__body {
                border-radius: 0 0 $measure--half $measure--half;
            }
        }

        &[data-open='false'] {
            button {
                &:focus,
                &:active,
                &:hover {
                    border-radius: $measure--half;
                }

                div {
                    border-bottom: none;
                }
            }
        }
    }

    .accordion__heading__text {
        @include extrasmalltype;
    }
}
